def apply_demo2_rule_final(grid):
    """Rule: Each isolated 1 produces specific 7-cell pattern; all 1s are sources"""
    result = [[None for _ in range(len(grid[0]))] for _ in range(len(grid))]

    h, w = len(grid), len(grid[0])
    bg_val = 5

    # First pass: initialize everything to background
    for r in range(h):
        for c in range(w):
            result[r][c] = bg_val

    # Second pass: mark non-1 non-background cells
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val != bg_val and val != 1:
                result[r][c] = val

    # Third pass: process each 1 and generate pattern
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val == 1:
                offsets = [
                    (-2, 0, 7),   # Row above by 2
                    (-1, 0, 8),   # Row above by 1
                    (-1, 1, 6),   # Row above by 1, right 1
                    (0, 0, 9),    # Same position - becomes 9
                    (1, -1, 9),   # Below by 1, left 1
                    (1, 0, 6),    # Below by 1
                    (2, -1, 8),   # Below by 2, left 1
                ]

                for dr, dc, dv in offsets:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w:
                        if result[nr][nc] == bg_val:
                            result[nr][nc] = dv

    return result

