def apply_demo1_rule(grid):
    """Rule: Each isolated 7 produces "4 4 0 0 0" pattern; background preserved"""
    result = [[None for _ in range(len(grid[0]))] for _ in range(len(grid))]
    bg_val = 8

    # Initialize with background
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            result[r][c] = grid[r][c]

    # Process each 7 - but don't preserve non-background non-7 cells either
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val == 7:
                offsets = [(-3, -2, 4), (-2, -1, 4), (-1, 0, 0), (0, 1, 0), (1, 2, 0)]
                for dr, dc, dv in offsets:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < len(result) and 0 <= nc < len(result[nr]):
                        if result[nr][nc] == bg_val:
                            result[nr][nc] = dv

    return result

def apply_demo2_rule(grid):
    """Rule: Each isolated 1 produces specific 7-cell pattern; all 1s are sources"""
    result = [[None for _ in range(len(grid[0]))] for _ in range(len(grid))]
    bg_val = 5

    for r in range(len(grid)):
        for c in range(len(grid[r])):
            result[r][c] = bg_val

    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val != bg_val and val != 1:
                result[r][c] = val

    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val == 1:
                offsets = [
                    (-2, 0, 7), (-1, 0, 8), (-1, 1, 6), 
                    (0, 0, 9), (1, -1, 9), (1, 0, 6), (2, -1, 8)
                ]
                for dr, dc, dv in offsets:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < len(result) and 0 <= nc < len(result[nr]):
                        if result[nr][nc] == bg_val:
                            result[nr][nc] = dv

    return result

