    bg = grid[r][c]
    nbs = []
    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        nr, nc = r+dr, c+dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[nr]):
            if grid[nr][nc] != bg:
                nbs.append((nr, nc))
    return nbs

def is_clustered(r, c, grid):
    """Check if this cell has non-background adjacent neighbors"""
    # Get unique non-bg values around this cell
    seen = set()
    seen.add(grid[r][c])
    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        nr, nc = r+dr, c+dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[nr]):
            seen.add(grid[nr][nc])
    # Clustered if more than 1 distinct non-bg value nearby
    return len(seen) > 1

def apply_diagonal_pattern(grid, r, c):
    """Apply Demo 2-style diagonal pattern to an isolated cell"""
    bg_val = grid[r][c]

    result = [[bg_val for _ in range(len(grid[0]))] for _ in range(len(grid))]

